1028	export async function listMembers(
1029	  input: ListMembersInput,
1030	): Promise<Page<MemberWithUser>> {
1031	  const db = getDb();
1032	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
1033	
1034	  const filters = compact(
1035	    orgPredicate(members.orgId, input.orgId),
1036	    liveMemberPredicate(),
1037	    input.role === undefined ? undefined : eq(members.role, input.role),
1038	    input.status === undefined ? undefined : eq(members.status, input.status),
1039	    input.query === undefined
1040	      ? undefined
1041	      : or(
1042	          like(users.name, `%${input.query}%`),
1043	          like(users.email, `%${input.query}%`),
1044	        ),
1045	  );
1046	
1047	  const total = db
1048	    .select({ value: count() })
1049	    .from(members)
1050	    .innerJoin(users, eq(users.id, members.userId))
1051	    .where(and(...filters))
1052	    .get();
1053	
1054	  const rows = db
1055	    .select({ member: members, user: users })
1056	    .from(members)
1057	    .innerJoin(users, eq(users.id, members.userId))
1058	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
1059	    .orderBy(desc(members.createdAt), desc(members.id))
1060	    .limit(probeLimit(input.limit))
1061	    .all();
