833	/** Same decision as `can()`, but reports why — used by the settings UI. */
834	export function explain(
835	  actor: Actor,
836	  action: PermissionAction,
837	  resource: PermissionResource,
838	): PermissionDecision {
839	  const base = { action, resourceKind: resource.kind } as const;
840	
841	  if (actor.orgId !== resource.orgId) {
842	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
843	  }
844	
845	  if (actor.isPlatformStaff === true) {
846	    return { ...base, allowed: true, reason: "granted_by_staff" };
847	  }
848	
849	  const required = ROLE_MATRIX[action];
850	  if (required === undefined) {
851	    return { ...base, allowed: false, reason: "denied_unknown_action" };
852	  }
853	
854	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
855	    return { ...base, allowed: true, reason: "granted_by_role" };
856	  }
857	
858	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
859	    return { ...base, allowed: true, reason: "granted_by_ownership" };
860	  }
861	
862	  return { ...base, allowed: false, reason: "denied_by_role" };
863	}
