/**
 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
 */
import {
  getLimit,
  getPlanLimits,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, billingResource, requireFound } from "./_support";
import type {
  CancelSubscriptionInput,
  ChangePlanInput,
  UpdateSeatsInput,
} from "@/schemas/billing";
import type {
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function getBillingSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<BillingSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(orgId),
    "Subscription",
    orgId,
  );

  const checks = await Promise.all(
    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
  );

  const limits = getPlanLimits(subscription.plan);

  return {
    orgId,
    subscription,
    checks,
    upcomingInvoiceCents:
      limits.priceCentsPerSeatMonthly *
      subscription.seats *
      (subscription.interval === "annual" ? 12 : 1),
  };
}

/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
  );

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}
import type { Actor, Role } from "@/types/member";
import { ROLE_RANK } from "@/types/member";
import type {
  PermissionAction,
  PermissionDecision,
  PermissionResource,
} from "@/types/permission";

/**
 * The single authorization entry point for Taskflow.
 *
 * Every Server Action, service method, Route Handler and permission-sensitive
 * UI component funnels through `can()`. Nothing else may branch on
 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 *
 * Decision order:
 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 *   2. platform staff bypass
 *   3. role matrix lookup
 *   4. ownership escalations (authors edit their own issues/comments)
 */

/** Minimum role required for each action, before ownership escalations. */
export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
  "org:read": "viewer",
  "org:update": "admin",
  "org:delete": "owner",
  "org:manage_billing": "owner",
  "org:manage_flags": "admin",
  "member:read": "viewer",
  "member:invite": "admin",
  "member:update_role": "admin",
  "member:remove": "admin",
  "project:create": "member",
  "project:read": "viewer",
  "project:update": "member",
  "project:archive": "admin",
  "project:delete": "owner",
  "issue:create": "member",
  "issue:read": "viewer",
  "issue:update": "member",
  "issue:assign": "member",
  "issue:archive": "member",
  "issue:delete": "admin",
  "comment:create": "member",
  "comment:read": "viewer",
  "comment:update": "member",
  "comment:delete": "admin",
  "activity:read": "member",
  "activity:export": "admin",
  "notification:read": "viewer",
  "notification:manage": "viewer",
  "webhook:manage": "admin",
};

/** Actions an actor may perform on their own content regardless of role rank. */
const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
  "issue:update": true,
  "issue:archive": true,
  "comment:update": true,
  "comment:delete": true,
  "notification:manage": true,
};

function isOwnedByActor(
  actor: Actor,
  resource: PermissionResource,
): boolean {
  switch (resource.kind) {
    case "issue":
      return (
        resource.authorId === actor.userId ||
        resource.assigneeId === actor.userId
      );
    case "comment":
      return resource.authorId === actor.userId;
    case "project":
      return resource.leadId === actor.userId;
    case "notification":
      return resource.recipientId === actor.userId;
    case "member":
      return resource.targetUserId === actor.userId;
    default:
      return false;
  }
}

/**
 * Answers "may this actor perform this action on this resource?".
 *
 * @param actor    the authenticated principal, always scoped to one org
 * @param action   a member of the closed `PermissionAction` vocabulary
 * @param resource the object being acted on, discriminated on `kind`
 */
export function can(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): boolean {
  return explain(actor, action, resource).allowed;
}

/** Same decision as `can()`, but reports why — used by the settings UI. */
export function explain(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): PermissionDecision {
  const base = { action, resourceKind: resource.kind } as const;

  if (actor.orgId !== resource.orgId) {
    return { ...base, allowed: false, reason: "denied_cross_tenant" };
  }

  if (actor.isPlatformStaff === true) {
    return { ...base, allowed: true, reason: "granted_by_staff" };
  }

  const required = ROLE_MATRIX[action];
  if (required === undefined) {
    return { ...base, allowed: false, reason: "denied_unknown_action" };
  }

  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
    return { ...base, allowed: true, reason: "granted_by_role" };
  }

  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
    return { ...base, allowed: true, reason: "granted_by_ownership" };
  }

  return { ...base, allowed: false, reason: "denied_by_role" };
}

/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
export class PermissionDeniedError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly action: PermissionAction,
    readonly decision: PermissionDecision,
  ) {
    super(`Permission denied: ${action} on ${decision.resourceKind}`);
    this.name = "PermissionDeniedError";
  }
}

/** Throwing variant of `can()` for service-layer guard clauses. */
export function assertCan(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): void {
  const decision = explain(actor, action, resource);
  if (!decision.allowed) {
    throw new PermissionDeniedError(action, decision);
  }
}

/** Bulk evaluation used by navigation and toolbar components. */
export function canAll(
  actor: Actor,
  actions: readonly PermissionAction[],
  resource: PermissionResource,
): boolean {
  return actions.every((action) => can(actor, action, resource));
}
import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
  if (!row) return null;
  return row.orgId === actor.orgId ? row : null;
}

/**
 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 * cannot forget it. Always spread the caller filter first.
 */
export function withOrgScope<T extends object>(
  actor: Actor,
  filter: T,
): T & { orgId: OrgId } {
  return { ...filter, orgId: actor.orgId };
}
/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}
/**
 * Deterministic factories for actors, orgs, projects, issues and comments
 * used across the suite.
 *
 * Every factory seeds from the same `idFactory`, so a test that does not care
