142	import { emit } from "@/lib/event-bus";
143	import { assertCan } from "@/lib/permissions";
144	import { assertOrgScope } from "@/lib/tenant";
145	import * as memberRepo from "@/server/repositories/member-repository";
146	import { hasRoleAtLeast } from "@/types/member";
147	import { actorEnvelope, memberResource, requireFound } from "./_support";
148	import type {
149	  ListMembersInput,
