159	export async function listMembers(
160	  actor: Actor,
161	  input: ListMembersInput,
162	): Promise<Page<MemberWithUser>> {
163	  assertOrgScope(actor, input.orgId);
164	  assertCan(actor, "member:read", {
165	    kind: "organization",
166	    orgId: input.orgId,
167	  });
168	  return memberRepo.listMembers(input);
