243	/**
244	 * Turns a (user, org) pair into the `Actor` every service method takes. The
245	 * only place an `Actor` is minted from stored state — jobs and the session
246	 * layer both come through here.
247	 */
248	export async function resolveActor(
249	  userId: UserId,
250	  orgId: OrgId,
251	): Promise<Actor | null> {
252	  const member = await memberRepo.findMember(orgId, userId);
253	  if (!member || member.status !== "active") return null;
254	
255	  return { userId, orgId, role: member.role };
