305	/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
306	export class NotFoundError extends Error {
307	  readonly code = "not_found" as const;
308	
309	  constructor(
310	    readonly entity: string,
311	    readonly id: string,
312	  ) {
313	    super(`${entity} ${id} was not found`);
314	    this.name = "NotFoundError";
315	  }
