318	/** Unwraps a repository read, turning the `null` case into a domain error. */
319	export function requireFound<T>(
320	  value: T | null | undefined,
321	  entity: string,
322	  id: string,
323	): T {
324	  if (value === null || value === undefined) {
325	    throw new NotFoundError(entity, id);
326	  }
327	  return value;
328	}
