531	/** The failure envelope a Server Action returns instead of throwing. */
532	export function toActionResult(error: unknown): ActionResult<never> {
533	  return {
534	    ok: false,
535	    error: toAppError(error),
536	    submittedAt: new Date().toISOString(),
537	  };
