323	/** Groups a feed page by calendar day, newest day first. */
324	export function groupByDay(
325	  events: readonly ActivityEvent[],
326	): readonly ActivityGroup[] {
327	  const byDay = new Map<string, ActivityEvent[]>();
328	
329	  for (const event of events) {
330	    const day = event.occurredAt.slice(0, 10);
331	    const bucket = byDay.get(day) ?? [];
332	    bucket.push(event);
333	    byDay.set(day, bucket);
334	  }
335	
336	  return [...byDay.entries()]
337	    .sort(([a], [b]) => (a < b ? 1 : -1))
338	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
339	}
