560	/**
561	 * The one place a quota is evaluated. Every guard elsewhere calls this rather
562	 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
563	 * exactly two files: `plan-limits.ts` and `usageFor()` below.
564	 */
565	export async function checkLimit(
566	  orgId: OrgId,
567	  resource: LimitedResource,
568	  requested = 1,
569	): Promise<LimitCheck> {
570	  const plan = await planFor(orgId);
571	  const used = await usageFor(orgId, resource);
572	  const limit = getLimit(plan, resource);
573	
574	  return {
575	    resource,
576	    plan,
577	    limit,
578	    used,
579	    remaining: Math.max(0, limit - used),
580	    exceeded: wouldExceedLimit(plan, resource, used, requested),
581	  };
582	}
