584	/** Throwing form used by the create paths, and it emits the breach event. */
585	export async function assertWithinLimit(
586	  orgId: OrgId,
587	  resource: LimitedResource,
588	  requested = 1,
589	): Promise<void> {
590	  const check = await checkLimit(orgId, resource, requested);
591	  if (!check.exceeded) return;
592	
593	  await emit("billing.limit_exceeded", {
594	    orgId,
595	    actorId: null,
596	    occurredAt: toIsoTimestamp(new Date()),
597	    resource,
598	    limit: check.limit,
599	    used: check.used,
600	  });
601	
602	  throw new Error(
603	    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
604	  );
605	}
