708	/** Maps a quota dimension onto the counter that measures it. */
709	async function usageFor(
710	  orgId: OrgId,
711	  resource: LimitedResource,
712	): Promise<number> {
713	  const usage = await usageRepo.getUsage(orgId);
714	
715	  switch (resource) {
716	    case "seats":
717	      return usage.seatsUsed;
718	    case "projects":
719	      return usage.projectsUsed;
720	    case "issuesPerProject":
721	      return usage.issuesUsed;
722	    case "storageMb":
723	      return usage.storageMbUsed;
724	    case "webhooks":
725	      return webhookRepo.countEndpoints(orgId);
