import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as org from "@/server/services/organization-service";
import * as billing from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("handover", () => {
  it("full flow", async () => {
    const off = registerActivityListeners();
    const t = await createTenant("ho-a");
    const other = await createTenant("ho-b");
    const events: unknown[] = [];
    subscribe("member.role_changed", (p) => { events.push(["rc", p]); });
    subscribe("organization.ownership_transferred", (p) => { events.push(["ot", p]); });

    await expect(org.initiateOwnershipHandover(t.actors.admin, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(org.initiateOwnershipHandover(t.actors.owner, other.org.id, t.userIds.member)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, other.userIds.member)).rejects.toBeInstanceOf(NotFoundError);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner)).rejects.toMatchObject({ reason: "self" });
    await expect(org.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });

    const h = await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(new Date(h.expiresAt).getTime() - new Date(h.createdAt).getTime()).toBe(7 * 864e5);
    expect(h.status).toBe("pending");
    expect(await org.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toEqual(h);
    expect(await org.getPendingOwnershipHandover(other.actors.viewer, other.org.id)).toBeNull();
    const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, limit: 10, cursor: null } as never);
    expect(notes.items.map((n) => n.kind)).toEqual(["ownership_handover"]);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin)).rejects.toMatchObject({ reason: "pending_exists" });
    await expect(org.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });

    const c = await org.cancelOwnershipHandover(t.actors.owner, t.org.id);
    expect(c.status).toBe("canceled"); expect(c.resolvedAt).not.toBeNull();
    await expect(org.declineOwnershipHandover(t.actors.member, t.org.id)).rejects.toBeInstanceOf(OwnershipHandoverError);

    await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    const after = await org.acceptOwnershipHandover(t.actors.member, t.org.id);
    expect(after.ownerId).toBe(t.userIds.member);
    expect(events.map((e) => (e as [string])[0])).toEqual(["rc", "rc", "ot"]);
    expect(events.every((e) => (e as [string, { actorId: string }])[1].actorId === t.userIds.member)).toBe(true);
    expect((await memberRepo.findMember(t.org.id, t.userIds.owner))?.role).toBe("admin");
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))?.role).toBe("owner");
    await expect(org.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });

    await expect(billing.changePlan(t.actors.owner, { orgId: t.org.id, plan: "enterprise", interval: "monthly" } as never)).rejects.toBeInstanceOf(PermissionDeniedError);
    await billing.changePlan(t.actors.member, { orgId: t.org.id, plan: "enterprise", interval: "monthly" } as never);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin)).rejects.toBeInstanceOf(PermissionDeniedError);

    const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
    const a = acts.items.find((x) => x.action === "organization.ownership_transferred");
    expect(a).toMatchObject({ subjectKind: "organization", subjectId: t.org.id, actorId: t.userIds.member, metadata: { fromUserId: t.userIds.owner, toUserId: t.userIds.member } });

    // new member alert goes to new owner
    const u = await userRepo.insertUser({ email: "n@x.test", name: "n", passwordHash: "s" });
    const { emit } = await import("@/lib/event-bus");
    const m = await memberRepo.insertMember(t.org.id, u.id, "member", null);
    await emit("member.joined", { orgId: t.org.id, actorId: u.id, occurredAt: new Date().toISOString() as never, memberId: m.id, userId: u.id, role: "member" });
    const n2 = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, limit: 10, cursor: null } as never);
    expect(n2.items.some((n) => n.kind === "member_joined")).toBe(true);

    // offer then remove offered member -> auto withdrawn; remove prev owner
    await org.initiateOwnershipHandover(t.actors.member, t.org.id, t.userIds.viewer);
    const viewer = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    await memberService.removeMember(t.actors.member, { orgId: t.org.id, memberId: viewer!.id });
    expect(await org.getPendingOwnershipHandover(t.actors.admin, t.org.id)).toBeNull();
    const prev = await memberRepo.findMember(t.org.id, t.userIds.owner);
    await memberService.removeMember(t.actors.member, { orgId: t.org.id, memberId: prev!.id });
    off();
  });

  it("expiry", async () => {
    const t = await createTenant("ho-c");
    vi.useFakeTimers({ toFake: ["Date"] });
    const T = new Date("2027-01-01T00:00:00.000Z");
    vi.setSystemTime(T);
    await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    vi.setSystemTime(new Date(T.getTime() + 7 * 864e5 - 1));
    expect(await org.getPendingOwnershipHandover(t.actors.admin, t.org.id)).not.toBeNull();
    vi.setSystemTime(new Date(T.getTime() + 7 * 864e5));
    expect(await org.getPendingOwnershipHandover(t.actors.admin, t.org.id)).toBeNull();
    await expect(org.acceptOwnershipHandover(t.actors.viewer, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    await expect(org.declineOwnershipHandover(t.actors.viewer, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    await expect(org.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(org.cancelOwnershipHandover(t.actors.owner, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    const h = await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin);
    expect(h.status).toBe("pending");
    const d = await org.declineOwnershipHandover(t.actors.admin, t.org.id);
    expect(d.status).toBe("declined");
    vi.useRealTimers();
  });
});
